+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.Notification.Position;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>();
+    private final MessageStore messageStore;
+    private boolean resettingAfterSend;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setWidthFull();
+        send.addClickListener(event -> sendMessage());
+        for (HasValue<?, ?> field : new HasValue<?, ?>[] {name, email, phone, message}) {
+            field.addValueChangeListener(event -> handleEdit());
+        }
+        Shortcuts.addShortcutListener(UI.getCurrent(), this::sendMessage, Key.ENTER)
+                .bindLifecycleTo(this);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setItems(messageStore.getNewestFirst());
+        messages.setWidthFull();
+
+        add(name, email, phone, message, send, messages);
+        setWidth("100%");
+    }
+
+    private void handleEdit() {
+        if (resettingAfterSend) {
+            return;
+        }
+        send.setEnabled(true);
+        clearValidation();
+    }
+
+    private void sendMessage() {
+        if (!send.isEnabled()) {
+            return;
+        }
+
+        clearValidation();
+        boolean valid = true;
+
+        if (isBlank(name.getValue())) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = value(email.getValue()).trim();
+        String phoneValue = value(phone.getValue()).trim();
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        String messageValue = value(message.getValue());
+        if (messageValue.isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        }
+        if (messageValue.length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(value(name.getValue()), value(email.getValue()),
+                value(phone.getValue()), messageValue));
+        messages.setItems(messageStore.getNewestFirst());
+        Notification.show("Message sent", 3000, Position.BOTTOM_START);
+
+        resettingAfterSend = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearValidation();
+        resettingAfterSend = false;
+        send.setEnabled(false);
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private boolean hasUnsavedInput() {
+        return !value(name.getValue()).isEmpty()
+                || !value(email.getValue()).isEmpty()
+                || !value(phone.getValue()).isEmpty()
+                || !value(message.getValue()).isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        var navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add("You have an unsent message. What would you like to do?");
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            navigation.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    private static String value(String value) {
+        return value == null ? "" : value;
+    }
+}
