+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @Autowired
+    private MessageStore store;
+
+    @Test
+    void validatesMalformedEmailAndLongMessageAndSubmitsWithEnter() {
+        int initialCount = store.getNewestFirst().size();
+        navigate(ContactView.class);
+        test($(TextField.class).withLabel("Name").single()).setValue("Grace");
+        EmailField email = $(EmailField.class).single();
+        test(email).setValue("not-an-email");
+        TextArea message = $(TextArea.class).single();
+        test(message).setValue("m".repeat(501));
+        test($(Button.class).withText("Send").single()).click();
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(initialCount, store.getNewestFirst().size());
+
+        test(email).setValue("grace@example.com");
+        test(message).setValue("A valid message");
+        fireShortcut(Key.ENTER);
+        assertEquals(initialCount + 1, store.getNewestFirst().size());
+        assertEquals("Grace", store.getNewestFirst().getFirst().name());
+    }
+
+    @Test
+    void validatesSendsAndKeepsMessagesAfterNavigation() {
+        int initialCount = store.getNewestFirst().size();
+        ContactView contact = navigate(ContactView.class);
+        Button send = $(Button.class).withText("Send").single();
+        assertTrue(send.isEnabled());
+
+        test(send).click();
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).single();
+        TextArea message = $(TextArea.class).single();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertEquals(initialCount, test($(Grid.class).single()).size());
+
+        test(name).setValue("Ada");
+        test($(TextField.class).withLabel("Phone").single()).setValue("555-0100");
+        test(message).setValue("Hello");
+        test(send).click();
+
+        assertEquals(initialCount + 1, test($(Grid.class).single()).size());
+        assertEquals("Ada", test($(Grid.class).single()).getCellText(0, 0));
+        assertEquals("Hello", test($(Grid.class).single()).getCellText(0, 1));
+        assertFalse(send.isEnabled());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+
+        test($(TextField.class).withLabel("Phone").single()).setValue("changed");
+        assertTrue(send.isEnabled());
+        assertThrows(IllegalArgumentException.class, () -> navigate(AboutView.class));
+        assertSameCurrent(contact);
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertSameCurrent(contact);
+        assertEquals("changed", $(TextField.class).withLabel("Phone").single().getValue());
+
+        assertThrows(IllegalArgumentException.class, () -> navigate(AboutView.class));
+        test($(Button.class).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+        navigate(ContactView.class);
+        assertEquals(initialCount + 1, test($(Grid.class).single()).size());
+        assertEquals("Ada", test($(Grid.class).single()).getCellText(0, 0));
+        navigate(AboutView.class);
+        assertFalse($(Dialog.class).exists());
+    }
+
+    private void assertSameCurrent(ContactView expected) {
+        assertEquals(expected, getCurrentView());
+    }
+}
